// Shared lesson runtime.
// Saves per-student lesson progress through Part A's db.js.
//
// Also provides:
//  - Review mode: "Practice the ones I got wrong" filters a lesson down to
//    just the questions that took more than one attempt, and lets the
//    student retry them fresh.
//  - Read-aloud: speaker buttons use the browser's built-in SpeechSynthesis
//    API (fully offline, no network/audio files needed) to read the lesson
//    text and each quiz question + its options in the active language.
//  - Printable practice sheet: opens a clean, answer-free, print-ready sheet
//    of a lesson's questions that can be printed or saved as a PDF from the
//    browser's print dialog — useful for students without device access.

import { saveProgress, getProgress } from '../shared/db.js';
import { raiseHand, lowerHand, getRaisedHands, onHandsChanged } from '../shared/live-signal.js';

const quizState = new WeakMap();

// A student can only be stuck on one question at a time, so raising a new
// hand replaces any earlier one. Keeps every "I'm stuck" button on screen in
// sync with that single source of truth — including resetting back to
// normal the moment the teacher resolves it from the Teacher Board (or the
// student raised/lowered it from another tab on this same device; see
// src/shared/live-signal.js for exactly what "live" means here).
onHandsChanged(() => syncRaiseHandButtons());

function syncRaiseHandButtons() {
  const student = currentStudent();
  const buttons = document.querySelectorAll('.quiz-raise-btn');
  if (!buttons.length) return;
  const mine = student ? getRaisedHands().find((h) => h.studentId === student.studentId) : null;
  buttons.forEach((btn) => {
    const quiz = btn.closest('.quiz');
    const isThisOne = !!mine && quiz && quiz.dataset.lessonId === mine.lessonId && String(quiz.dataset.questionIndex) === String(mine.questionIndex);
    updateRaiseHandChrome(btn, isThisOne);
  });
}

// Question-specific hints are deliberately answer-neutral: they remind the
// learner what relationship or method to use without naming the answer.
const HINT_BANK = {
  l1: [
    { en:'Think about the number that comes immediately before the given number.', hi:'दी गई संख्या से ठीक पहले आने वाली संख्या के बारे में सोचें।' },
    { en:'Think about the number that comes immediately after the given number.', hi:'दी गई संख्या के ठीक बाद आने वाली संख्या के बारे में सोचें।' },
    { en:'Whole numbers begin at the starting point of the whole-number number line.', hi:'पूर्ण संख्याओं की संख्या रेखा के शुरुआती बिंदु पर ध्यान दें।' },
    { en:'Check which operation keeps the result within the set of whole numbers for every whole-number pair.', hi:'देखें कि कौन-सी संक्रिया हर दो पूर्ण संख्याओं के लिए परिणाम को पूर्ण संख्या ही रखती है।' },
    { en:'On a number line, a number farther to the right has the greater value.', hi:'संख्या रेखा पर दाईं ओर की संख्या का मान अधिक होता है।' },
    { en:'Think of multiplication as equal groups and count the total in all the groups.', hi:'गुणा को बराबर समूहों के रूप में सोचें और सभी समूहों की कुल संख्या गिनें।' }
  ],
  l2: [
    { en:'Equivalent fractions name the same part of a whole even when the numbers look different.', hi:'समतुल्य भिन्न पूरे के समान भाग को बताती हैं, भले ही संख्याएँ अलग दिखें।' },
    { en:'The denominator tells the total number of equal slices, while the numerator tells how many were taken.', hi:'हर बराबर टुकड़ों की कुल संख्या बताता है और अंश लिए गए टुकड़ों की संख्या।' },
    { en:'Look for a fraction that represents the same half of a whole.', hi:'ऐसी भिन्न खोजें जो पूरे के उसी आधे भाग को दर्शाती हो।' },
    { en:'When the denominators are the same, compare the numerators.', hi:'जब हर समान हों, तो अंशों की तुलना करें।' },
    { en:'The parts have the same denominator, so focus on the numerators when combining them.', hi:'दोनों भिन्नों के हर समान हैं, इसलिए जोड़ते समय अंशों पर ध्यान दें।' },
    { en:'A proper fraction has a numerator smaller than its denominator.', hi:'उचित भिन्न में अंश हर से छोटा होता है।' }
  ],
  l3: [
    { en:'Recall the standard angle classifications and their degree measures.', hi:'कोणों के सामान्य प्रकार और उनके माप याद करें।' },
    { en:'Count the straight sides that meet to make the corners of the shape.', hi:'आकृति के कोने बनाने वाली सीधी भुजाओं की संख्या गिनें।' },
    { en:'A right angle is the corner you see in a square or rectangle.', hi:'समकोण वही कोना है जो वर्ग या आयत में दिखाई देता है।' },
    { en:'Look for the shape whose four sides all have the same length.', hi:'उस आकृति को खोजें जिसकी चारों भुजाओं की लंबाई समान हो।' },
    { en:'Compare the angle with the benchmark of a right angle.', hi:'कोण की तुलना समकोण के माप से करें।' },
    { en:'Vertices are the corner points where sides meet.', hi:'शीर्ष वे कोने के बिंदु हैं जहाँ भुजाएँ मिलती हैं।' }
  ],
  s1: [
    { en:'Think about the plant part that is usually below the soil and takes in water.', hi:'उस पौधे के भाग के बारे में सोचें जो सामान्यतः मिट्टी के नीचे होता है और पानी लेता है।' },
    { en:'Think about the plant part that uses sunlight to prepare food.', hi:'उस पौधे के भाग के बारे में सोचें जो सूर्य के प्रकाश की मदद से भोजन बनाता है।' },
    { en:'Choose the food that comes from a plant rather than a mineral or manufactured material.', hi:'ऐसा भोजन चुनें जो पौधे से मिलता है, खनिज या निर्मित वस्तु से नहीं।' },
    { en:'Plants need light and other materials to prepare food; think about the main energy source.', hi:'पौधों को भोजन बनाने के लिए प्रकाश और अन्य पदार्थ चाहिए; मुख्य ऊर्जा स्रोत के बारे में सोचें।' },
    { en:'Think about the part that holds the plant upright and helps move water through it.', hi:'उस भाग के बारे में सोचें जो पौधे को सीधा रखता है और पानी पहुँचाने में मदद करता है।' },
    { en:'A plant grows, needs resources, and carries out life processes.', hi:'पौधा बढ़ता है, संसाधनों की आवश्यकता होती है और जीवन प्रक्रियाएँ करता है।' }
  ],
  s2: [
    { en:'Think about which state keeps its own shape instead of taking the container’s shape.', hi:'सोचें कि कौन-सी अवस्था बर्तन का आकार लेने के बजाय अपना आकार बनाए रखती है।' },
    { en:'Think about a state that can flow and take the shape of its container.', hi:'उस अवस्था के बारे में सोचें जो बह सकती है और बर्तन का आकार ले सकती है।' },
    { en:'Heating can cause one state of matter to change into another state.', hi:'गर्म करने पर पदार्थ की एक अवस्था दूसरी अवस्था में बदल सकती है।' },
    { en:'Think about the state whose particles spread out and occupy available space.', hi:'उस अवस्था के बारे में सोचें जिसके कण फैलकर उपलब्ध स्थान घेरते हैं।' },
    { en:'A liquid keeps its amount but changes its shape to match its container.', hi:'द्रव अपनी मात्रा बनाए रखता है लेकिन बर्तन के अनुसार आकार बदलता है।' },
    { en:'Air is made of particles that move freely and spread through space.', hi:'हवा ऐसे कणों से बनी है जो स्वतंत्र रूप से चलते हैं और स्थान में फैलते हैं।' }
  ]
};

function getHint(quiz) {
  const lessonId = quiz.dataset.lessonId;
  const index = Number(quiz.dataset.questionIndex || 0);
  return HINT_BANK[lessonId]?.[index] || {
    en:'Read the question carefully and connect it to the main idea from this lesson.',
    hi:'प्रश्न को ध्यान से पढ़ें और इसे इस पाठ के मुख्य विचार से जोड़ें।'
  };
}

function partialCreditForAttempts(attempts) {
  if (!attempts) return 0;
  return Math.max(0.25, Number((1 - ((attempts - 1) * 0.25)).toFixed(2)));
}

if (typeof window !== 'undefined') {
  // Stop any reading in progress when the student navigates away.
  window.addEventListener('hashchange', stopSpeaking);
  window.addEventListener('beforeunload', stopSpeaking);
}

export function applyLanguage(lang) {
  const target = lang === 'hi' ? 'hi' : 'en';
  document.querySelectorAll('[data-lang]').forEach((el) => {
    el.style.display = el.getAttribute('data-lang') === target ? '' : 'none';
  });
  document.querySelectorAll('.quiz').forEach((quiz) => refreshQuizChrome(quiz, target));
  stopSpeaking();
  refreshToolLabels(target);

  document.querySelectorAll('.lesson-content').forEach((lessonContent) => {
    const quizzes = Array.from(lessonContent.querySelectorAll('.quiz'));
    if (quizzes.length) renderReviewControl(lessonContent, quizzes);
  });
}

export async function initLesson(container, lang, student) {
  applyLanguage(lang);
  const quizzes = Array.from(container.querySelectorAll('.quiz'));
  quizzes.forEach((quiz, index) => {
    quiz.dataset.questionIndex = String(index);
    setupQuiz(quiz);
  });

  addLessonSpeakButton(container);
  addPrintButton(container);
  syncRaiseHandButtons();

  const lessonId = quizzes[0]?.dataset.lessonId;
  const lessonContent = container.querySelector('.lesson-content');

  if (!lessonId || !student?.studentId) {
    if (lessonContent && quizzes.length) renderReviewControl(lessonContent, quizzes);
    return;
  }

  try {
    const saved = await getProgress(lessonId, student.studentId);
    if (saved?.completedQuestions) {
      quizzes.forEach((quiz, index) => {
        const attempts = saved.questionAttempts?.[index] || 0;
        const wrong = saved.wrongOptions?.[index] || [];
        const history = saved.attemptHistory?.[index] || [];
        const state = quizState.get(quiz);
        if (state) state.history = history;

        if (saved.completedQuestions.includes(index)) {
          restoreCompletedQuiz(quiz, attempts || 1, saved.questionScores?.[index], saved.hintUsage?.[index], saved.hintHelped?.[index]);
        } else if (attempts > 0) {
          restoreInProgressQuiz(quiz, attempts, wrong, saved.hintUsage?.[index], saved.hintHelped?.[index]);
        }
      });
      showLessonProgress(container, saved, quizzes.length);
    }
  } catch (error) {
    console.warn('Could not restore lesson progress', error);
  }

  if (lessonContent && quizzes.length) renderReviewControl(lessonContent, quizzes);
}

function setupQuiz(quiz) {
  if (quizState.has(quiz)) return;
  quizState.set(quiz, { attempts: 0, done: false, currentWrong: null, history: [], sessionAttempts: 0, hintOpened: false, hintOpenedAttempt: null, hintOpenedSinceLastCorrect: false, hintHelped: false, questionScore: 0 });
  const options = Array.from(quiz.querySelectorAll('.quiz-option'));
  const feedbackEl = quiz.querySelector('.quiz-feedback');
  const counterEl = quiz.querySelector('.quiz-counter');

  options.forEach((btn) =>
    btn.addEventListener('click', () =>
      handleOptionClick(quiz, btn, options, feedbackEl, counterEl)
    )
  );

  addSpeakButton(quiz);
  addHintControl(quiz);
  addRaiseHandControl(quiz);
}

function currentLang() {
  return localStorage.getItem('preferredLang') === 'hi' ? 'hi' : 'en';
}

function currentStudent() {
  try { return JSON.parse(localStorage.getItem('offlineOrbitUser') || 'null'); }
  catch { return null; }
}

function handleOptionClick(quiz, btn, options, feedbackEl, counterEl) {
  const state = quizState.get(quiz);
  if (!state || state.done || btn.disabled) return;

  state.attempts += 1;
  state.sessionAttempts = (state.sessionAttempts || 0) + 1;
  state.history = state.history || [];
  state.history.push({
    attempt: state.attempts,
    optionIndex: options.indexOf(btn),
    selected: (btn.textContent || '').trim(),
    correct: btn.dataset.correct === 'true',
    hintOpened: !!state.hintOpenedSinceLastCorrect,
    hintHelped: false,
    timestamp: new Date().toISOString()
  });
  updateCounter(counterEl, state.attempts);
  const lang = currentLang();

  if (btn.dataset.correct === 'true') {
    state.done = true;
    state.currentWrong = null;
    state.questionScore = partialCreditForAttempts(state.attempts);
    state.hintHelped = !!state.hintOpenedSinceLastCorrect;
    if (state.history?.length) state.history[state.history.length - 1].hintHelped = !!state.hintHelped;
    options.forEach((opt) => { opt.disabled = true; });
    btn.classList.add('quiz-option--correct');
    renderFeedback(feedbackEl, lang, { type: 'correct', attempts: state.attempts, score: state.questionScore, hintHelped: state.hintHelped });
    saveLessonSnapshot(quiz.closest('.lesson-content')).catch((err) => console.error('Failed to save quiz progress', err));
    // Getting it right answers the question itself, so clear any raised
    // hand for it rather than leaving a stale "I'm stuck" on the board.
    const student = currentStudent();
    if (student) {
      const mine = getRaisedHands().find((h) => h.studentId === student.studentId);
      if (mine && mine.lessonId === quiz.dataset.lessonId && String(mine.questionIndex) === quiz.dataset.questionIndex) {
        lowerHand(student.studentId);
        syncRaiseHandButtons();
      }
    }
  } else {
    btn.disabled = true;
    btn.classList.add('quiz-option--wrong');
    state.currentWrong = btn;
    renderFeedback(feedbackEl, lang, { type: 'wrong', btn });
    saveLessonSnapshot(quiz.closest('.lesson-content')).catch((err) => console.error('Failed to save quiz progress', err));
  }
}

async function saveLessonSnapshot(lessonContent) {
  const student = currentStudent();
  const quizzes = Array.from(lessonContent?.querySelectorAll('.quiz') || []);
  const lessonId = quizzes[0]?.dataset.lessonId;

  // Even without a logged-in student, keep the review-mode button in sync.
  if (lessonContent && quizzes.length) renderReviewControl(lessonContent, quizzes);

  if (!student || !lessonId || !quizzes.length) return;

  const completedQuestions = [];
  const questionAttempts = {};
  const wrongOptions = {};
  const questionScores = {};
  const hintUsage = {};
  const hintHelped = {};
  const attemptHistory = {};
  const questionDetails = {};

  quizzes.forEach((quiz, index) => {
    const state = quizState.get(quiz);
    if (!state) return;
    questionAttempts[index] = state.attempts;
    attemptHistory[index] = state.history || [];
    questionScores[index] = state.done ? state.questionScore : 0;
    hintUsage[index] = !!state.hintOpened;
    hintHelped[index] = !!state.hintHelped;
    const questionEl = Array.from(quiz.querySelectorAll('.quiz-question')).find((el) => el.getAttribute('data-lang') === 'en') || quiz.querySelector('.quiz-question');
    const optionTexts = Array.from(quiz.querySelectorAll('.quiz-option')).map((opt) => (Array.from(opt.querySelectorAll('[data-lang="en"]'))[0] || opt).textContent.trim());
    questionDetails[index] = {
      question: (questionEl?.textContent || `Question ${index + 1}`).trim(),
      options: optionTexts,
      correctOption: Array.from(quiz.querySelectorAll('.quiz-option')).findIndex((opt) => opt.dataset.correct === 'true')
    };

    // Persist wrong choices so an unfinished lesson can resume accurately
    // after a refresh or when the app is reopened offline.
    wrongOptions[index] = Array.from(quiz.querySelectorAll('.quiz-option'))
      .map((opt, optionIndex) => opt.disabled && opt.dataset.correct !== 'true' ? optionIndex : null)
      .filter((optionIndex) => optionIndex !== null);

    if (state.done) {
      completedQuestions.push(index);
    }
  });

  const totalAttempts = Object.values(questionAttempts).reduce((sum, n) => sum + n, 0);
  const completed = completedQuestions.length === quizzes.length;
  const completedScores = completedQuestions.map(index => questionScores[index]).filter(value => typeof value === 'number');
  const score = completedScores.length
    ? Number((completedScores.reduce((a, b) => a + b, 0) / quizzes.length).toFixed(2))
    : 0;
  const hintOpenedCount = Object.values(hintUsage).filter(Boolean).length;
  const hintHelpedCount = Object.values(hintHelped).filter(Boolean).length;

  try {
    await saveProgress(lessonId, {
      completed,
      score,
      attempts: totalAttempts,
      completedQuestions,
      totalQuestions: quizzes.length,
      questionAttempts,
      wrongOptions,
      questionDetails,
      attemptHistory,
      questionScores,
      hintUsage,
      hintHelped,
      hintOpenedCount,
      hintHelpedCount,
      timestamp: new Date().toISOString(),
      studentName: student.name,
      classId: student.classId
    }, student.studentId);

    updateLessonProgressBanner(lessonContent, completedQuestions.length, quizzes.length, score);
  } catch (error) {
    console.warn('Progress could not be saved', error);
  }
}

function restoreCompletedQuiz(quiz, attempts, savedScore = null, hintUsed = false, hintHelped = false) {
  const state = quizState.get(quiz);
  if (!state) return;
  state.attempts = attempts;
  state.sessionAttempts = 0;
  state.history = state.history || [];
  state.done = true;
  state.questionScore = typeof savedScore === 'number' && savedScore > 0 ? savedScore : partialCreditForAttempts(attempts);
  state.hintOpened = !!hintUsed;
  state.hintOpenedSinceLastCorrect = !!hintUsed;
  state.hintHelped = !!hintHelped;
  state.hintOpenedAttempt = null;
  const options = Array.from(quiz.querySelectorAll('.quiz-option'));
  options.forEach((opt) => { opt.disabled = true; });
  const correct = options.find((opt) => opt.dataset.correct === 'true');
  if (correct) correct.classList.add('quiz-option--correct');
  updateCounter(quiz.querySelector('.quiz-counter'), attempts);
  renderFeedback(quiz.querySelector('.quiz-feedback'), currentLang(), {
    type: 'correct',
    attempts,
    score: state.questionScore,
    hintHelped: state.hintHelped
  });
}

function restoreInProgressQuiz(quiz, attempts, wrongOptionIndices = [], hintUsed = false, hintHelped = false) {
  const state = quizState.get(quiz);
  if (!state) return;

  state.attempts = attempts;
  state.sessionAttempts = 0;
  state.history = state.history || [];
  state.done = false;
  state.currentWrong = null;
  state.hintOpened = !!hintUsed;
  state.hintOpenedSinceLastCorrect = !!hintUsed;
  state.hintHelped = !!hintHelped;
  state.hintOpenedAttempt = null;

  const options = Array.from(quiz.querySelectorAll('.quiz-option'));
  wrongOptionIndices.forEach((index) => {
    const option = options[index];
    if (!option || option.dataset.correct === 'true') return;
    option.disabled = true;
    option.classList.add('quiz-option--wrong');
    state.currentWrong = option;
  });

  updateCounter(quiz.querySelector('.quiz-counter'), attempts);

  if (state.currentWrong) {
    renderFeedback(quiz.querySelector('.quiz-feedback'), currentLang(), {
      type: 'wrong',
      btn: state.currentWrong
    });
  }
}

function showLessonProgress(container, saved, total) {
  updateLessonProgressBanner(
    container.querySelector('.lesson-content'),
    saved.completedQuestions?.length || 0,
    total,
    saved.score || 0
  );
}

function updateLessonProgressBanner(lessonContent, done, total, score) {
  if (!lessonContent) return;
  let banner = lessonContent.querySelector('.lesson-progress-banner');
  if (!banner) {
    banner = document.createElement('div');
    banner.className = 'lesson-progress-banner';
    lessonContent.prepend(banner);
  }
  const lang = currentLang();
  banner.textContent = lang === 'hi'
    ? `प्रगति: ${done}/${total} प्रश्न पूरे • स्कोर ${Math.round(score * 100)}%`
    : `Progress: ${done}/${total} questions complete • Score ${Math.round(score * 100)}%`;
}

function updateCounter(counterEl, attempts) {
  if (counterEl) counterEl.dataset.attempts = String(attempts);
}

function addHintControl(quiz) {
  if (quiz.querySelector('.quiz-hint-wrap')) return;
  const wrap = document.createElement('div');
  wrap.className = 'quiz-hint-wrap';
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'quiz-hint-btn secondary-btn';
  button.setAttribute('aria-expanded', 'false');
  button.textContent = currentLang() === 'hi' ? '💡 संकेत देखें' : '💡 Show hint';
  const box = document.createElement('div');
  box.className = 'quiz-hint-box';
  box.hidden = true;
  const hint = getHint(quiz);
  box.innerHTML = `<span data-lang="en">${escapeHtml(hint.en)}</span><span data-lang="hi">${escapeHtml(hint.hi)}</span>`;
  button.addEventListener('click', () => {
    const state = quizState.get(quiz);
    if (!state || state.done) return;
    state.hintOpened = true;
    state.hintOpenedAttempt = state.attempts;
    state.hintOpenedSinceLastCorrect = true;
    box.hidden = !box.hidden;
    button.setAttribute('aria-expanded', String(!box.hidden));
    button.textContent = box.hidden
      ? (currentLang() === 'hi' ? '💡 संकेत देखें' : '💡 Show hint')
      : (currentLang() === 'hi' ? '💡 संकेत छिपाएँ' : '💡 Hide hint');
    applyLanguage(currentLang());
    saveLessonSnapshot(quiz.closest('.lesson-content')).catch(() => {});
  });
  wrap.append(button, box);
  const question = quiz.querySelector('.quiz-question');
  if (question) question.after(wrap); else quiz.prepend(wrap);
  updateHintChrome(quiz, currentLang());
}

function updateHintChrome(quiz, lang) {
  const btn = quiz.querySelector('.quiz-hint-btn');
  const box = quiz.querySelector('.quiz-hint-box');
  if (!btn || !box) return;
  btn.textContent = box.hidden
    ? (lang === 'hi' ? '💡 संकेत देखें' : '💡 Show hint')
    : (lang === 'hi' ? '💡 संकेत छिपाएँ' : '💡 Hide hint');
}

// "Raise hand" / I'm stuck — a per-question button that flags this exact
// question to the teacher. It shows up on the Teacher Board instantly if a
// board tab is already open on this device, and persists (via localStorage)
// so a board opened afterwards still sees it. See src/shared/live-signal.js.
function addRaiseHandControl(quiz) {
  if (quiz.querySelector('.quiz-raise-btn')) return;
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'quiz-raise-btn secondary-btn';
  btn.setAttribute('aria-pressed', 'false');

  const hintWrap = quiz.querySelector('.quiz-hint-wrap');
  const question = quiz.querySelector('.quiz-question');
  if (hintWrap) hintWrap.after(btn);
  else if (question) question.after(btn);
  else quiz.prepend(btn);

  btn.addEventListener('click', () => {
    const student = currentStudent();
    if (!student) return;
    const lessonId = quiz.dataset.lessonId;
    const questionIndex = Number(quiz.dataset.questionIndex);
    const alreadyRaised = getRaisedHands().some((h) =>
      h.studentId === student.studentId && h.lessonId === lessonId && h.questionIndex === questionIndex);

    if (alreadyRaised) {
      lowerHand(student.studentId);
    } else {
      const questionEl = Array.from(quiz.querySelectorAll('.quiz-question'))
        .find((el) => el.getAttribute('data-lang') === 'en') || question;
      raiseHand({
        studentId: student.studentId,
        name: student.name,
        classId: student.classId,
        lessonId,
        questionIndex,
        questionText: (questionEl?.textContent || '').trim()
      });
    }
    syncRaiseHandButtons();
  });

  updateRaiseHandChrome(btn, false);
}

function updateRaiseHandChrome(btn, active) {
  const lang = currentLang();
  btn.classList.toggle('is-raised', active);
  btn.setAttribute('aria-pressed', String(active));
  btn.textContent = active
    ? (lang === 'hi' ? '✋ शिक्षक को सूचित किया गया · रद्द करें' : '✋ Teacher notified · tap to cancel')
    : (lang === 'hi' ? '🙋 मुझे मदद चाहिए' : "🙋 I'm stuck");
}

function renderFeedback(feedbackEl, lang, info) {
  if (!feedbackEl) return;
  if (info.type === 'wrong') {
    const hint = lang === 'hi'
      ? (info.btn.dataset.remedialHi || 'यह सही उत्तर नहीं है। बचे हुए विकल्पों में से फिर से प्रयास करें।')
      : (info.btn.dataset.remedialEn || 'Not quite — try one of the remaining options.');
    feedbackEl.className = 'quiz-feedback quiz-feedback--wrong';
    feedbackEl.textContent = hint;
  } else {
    feedbackEl.className = 'quiz-feedback quiz-feedback--correct';
    const percent = Math.round((info.score ?? 1) * 100);
    const hintNote = info.hintHelped
      ? (lang === 'hi' ? ' संकेत ने अगली कोशिश में मदद की!' : ' The hint helped on your next try!')
      : '';
    feedbackEl.textContent = lang === 'hi'
      ? (info.attempts === 1 ? `बहुत बढ़िया! 100% अंक।${hintNote}` : `सही! ${info.attempts} प्रयासों के बाद ${percent}% आंशिक अंक मिले।${hintNote}`)
      : (info.attempts === 1 ? `Great job! 100% credit.${hintNote}` : `Correct! You earned ${percent}% partial credit after ${info.attempts} attempts.${hintNote}`);
  }
}

function refreshQuizChrome(quiz, lang) {
  const state = quizState.get(quiz);
  if (!state) return;
  updateHintChrome(quiz, lang);
  const raiseBtn = quiz.querySelector('.quiz-raise-btn');
  if (raiseBtn) updateRaiseHandChrome(raiseBtn, raiseBtn.classList.contains('is-raised'));
  const feedbackEl = quiz.querySelector('.quiz-feedback');
  if (state.done) renderFeedback(feedbackEl, lang, { type: 'correct', attempts: state.attempts, score: state.questionScore, hintHelped: state.hintHelped });
  else if (state.currentWrong) renderFeedback(feedbackEl, lang, { type: 'wrong', btn: state.currentWrong });
}

// ---------------------------------------------------------------------------
// Review mode — "Practice the ones I got wrong"
// ---------------------------------------------------------------------------

function strugglingIndices(quizzes) {
  return quizzes.reduce((indices, quiz, index) => {
    const state = quizState.get(quiz);
    if (state && state.attempts > 1) indices.push(index);
    return indices;
  }, []);
}

function renderReviewControl(lessonContent, quizzes) {
  if (!lessonContent) return;
  const struggled = strugglingIndices(quizzes);
  let bar = lessonContent.querySelector('.review-toolbar');
  const inReview = lessonContent.dataset.reviewMode === 'true';

  if (!struggled.length && !inReview) {
    bar?.remove();
    return;
  }

  if (!bar) {
    bar = document.createElement('div');
    bar.className = 'review-toolbar';
    const banner = lessonContent.querySelector('.lesson-progress-banner');
    if (banner) banner.after(bar);
    else lessonContent.prepend(bar);
  }

  const lang = currentLang();

  if (inReview) {
    bar.innerHTML = `
      <button type="button" class="secondary-btn review-btn" data-action="exit-review">
        ${lang === 'hi' ? '← पूरा पाठ देखें' : '← Back to full lesson'}
      </button>
      <span class="review-count">
        ${lang === 'hi' ? `${struggled.length} प्रश्नों की समीक्षा जारी` : `Reviewing ${struggled.length} question${struggled.length === 1 ? '' : 's'}`}
      </span>`;
  } else {
    bar.innerHTML = `
      <button type="button" class="primary-btn review-btn" data-action="enter-review">
        🔁 ${lang === 'hi'
          ? `जिन सवालों में गलती हुई उनका अभ्यास करें (${struggled.length})`
          : `Practice the ones I got wrong (${struggled.length})`}
      </button>`;
  }

  bar.onclick = (event) => {
    const btn = event.target.closest('button[data-action]');
    if (!btn) return;
    if (btn.dataset.action === 'enter-review') enterReview(lessonContent, quizzes);
    else exitReview(lessonContent, quizzes);
  };
}

function enterReview(lessonContent, quizzes) {
  const indices = strugglingIndices(quizzes);
  if (!indices.length) return;
  lessonContent.dataset.reviewMode = 'true';
  quizzes.forEach((quiz, index) => {
    if (indices.includes(index)) {
      quiz.style.display = '';
      resetQuizForRetry(quiz);
    } else {
      quiz.style.display = 'none';
    }
  });
  renderReviewControl(lessonContent, quizzes);
  quizzes.find((q) => q.style.display !== 'none')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function exitReview(lessonContent, quizzes) {
  lessonContent.dataset.reviewMode = 'false';
  quizzes.forEach((quiz) => { quiz.style.display = ''; });
  renderReviewControl(lessonContent, quizzes);
}

function resetQuizForRetry(quiz) {
  const state = quizState.get(quiz);
  if (!state) return;
  state.sessionAttempts = 0;
  state.done = false;
  state.currentWrong = null;
  state.hintOpened = false;
  state.hintOpenedAttempt = null;
  state.hintOpenedSinceLastCorrect = false;
  state.hintHelped = false;
  state.questionScore = 0;

  Array.from(quiz.querySelectorAll('.quiz-option')).forEach((opt) => {
    opt.disabled = false;
    opt.classList.remove('quiz-option--wrong', 'quiz-option--correct');
  });

  const feedbackEl = quiz.querySelector('.quiz-feedback');
  if (feedbackEl) {
    feedbackEl.textContent = '';
    feedbackEl.className = 'quiz-feedback';
  }
  updateCounter(quiz.querySelector('.quiz-counter'), 0);
}

// ---------------------------------------------------------------------------
// Read-aloud (SpeechSynthesis) — works fully offline, no network required.
// English-only: speak buttons are hidden entirely when the UI is in Hindi
// mode (see refreshToolLabels / addLessonSpeakButton / addSpeakButton).
// Each speak button is a toggle: the first click starts reading from the
// beginning; clicking the same button again while it's reading pauses it;
// clicking it again resumes from where it left off.
//
// SpeechSynthesis itself has no pause/resume position, so we fake one by
// splitting the text into sentence-sized chunks and speaking them one at a
// time. When the user stops mid-way, we remember which chunk we'd reached;
// the next click on the *same* button (with the same text) restarts the
// queue from that chunk instead of chunk 0. Navigating away, switching the
// UI language, or reading something else clears the remembered position, so
// a restart there does start over from the beginning.
// ---------------------------------------------------------------------------

function speechSupported() {
  return typeof window !== 'undefined' && 'speechSynthesis' in window;
}

// Splits text into sentence-ish chunks so playback can be resumed partway
// through instead of only ever restarting from the beginning.
function splitIntoSpeechChunks(text) {
  const matches = text.match(/[^.!?]+[.!?]+(?:\s+|$)|[^.!?]+$/g);
  const chunks = (matches || [text]).map((s) => s.trim()).filter(Boolean);
  return chunks.length ? chunks : [text];
}

// Tracks which single button (if any) is currently reading, since only one
// utterance can play at a time.
let activeSpeech = null; // { button, text, lang, chunks, chunkIndex }

// Remembers where a stopped reading left off, so the same button can resume
// instead of starting over. Cleared whenever playback finishes naturally,
// the text/lang changes, or the caller explicitly clears it (navigation,
// language switch, etc).
let pausedSpeech = null; // { button, text, lang, chunks, chunkIndex }

function isSpeakingButton(btn) {
  return !!activeSpeech && activeSpeech.button === btn;
}

function setButtonSpeakingUI(btn, speaking) {
  btn.classList.toggle('is-speaking', speaking);
  btn.setAttribute('aria-pressed', String(speaking));
  const lang = currentLang();
  if (btn.classList.contains('quiz-speak-btn')) {
    btn.textContent = speaking ? '⏹' : '🔊';
    btn.setAttribute('aria-label', speaking
      ? (lang === 'hi' ? 'पढ़ना रोकें' : 'Stop reading')
      : (lang === 'hi' ? 'यह प्रश्न ज़ोर से पढ़ें' : 'Read this question aloud'));
  } else if (btn.classList.contains('lesson-speak-btn')) {
    const label = speaking
      ? (lang === 'hi' ? 'रोकें' : 'Stop reading')
      : (lang === 'hi' ? 'पाठ सुनें' : 'Read lesson aloud');
    btn.innerHTML = `${speaking ? '⏹' : '🔊'} <span>${label}</span>`;
  }
}

// Stops any reading in progress. By default this also forgets the resume
// position; pass { keepPosition: true } to remember it instead (used when
// the user pauses the button that's currently reading).
function stopSpeaking(opts) {
  const keepPosition = !!(opts && opts.keepPosition);
  if (speechSupported()) window.speechSynthesis.cancel();
  if (activeSpeech) {
    setButtonSpeakingUI(activeSpeech.button, false);
    if (keepPosition && activeSpeech.chunkIndex < activeSpeech.chunks.length) {
      pausedSpeech = {
        button: activeSpeech.button,
        text: activeSpeech.text,
        lang: activeSpeech.lang,
        chunks: activeSpeech.chunks,
        chunkIndex: activeSpeech.chunkIndex,
      };
    } else if (!keepPosition) {
      pausedSpeech = null;
    }
    activeSpeech = null;
  } else if (!keepPosition) {
    pausedSpeech = null;
  }
}

function speakChunksFrom(button, chunks, startIndex, lang) {
  // Use an identity token for this playback session rather than matching on
  // `button` alone. speechSynthesis.cancel() fires an async 'error' (or
  // 'end') event on the utterance it just cut off; by the time that fires,
  // stopSpeaking() has already nulled activeSpeech and stashed the resume
  // position in pausedSpeech. Matching by identity (`activeSpeech === session`)
  // ensures that stray, post-cancel event sees this session as no longer
  // current and does nothing — instead of wiping the position we just saved.
  const session = { button, text: chunks.join(' '), lang, chunks, chunkIndex: startIndex };
  activeSpeech = session;
  setButtonSpeakingUI(button, true);

  const isCurrent = () => activeSpeech === session;

  const finish = () => {
    if (!isCurrent()) return; // stale event from an already-stopped session
    setButtonSpeakingUI(button, false);
    activeSpeech = null;
    if (pausedSpeech && pausedSpeech.button === button) pausedSpeech = null;
  };

  const speakNext = () => {
    // If the user stopped playback (or something else started speaking)
    // while the previous chunk was in flight, don't keep going.
    if (!isCurrent()) return;
    if (session.chunkIndex >= chunks.length) {
      finish();
      return;
    }
    const utterance = new SpeechSynthesisUtterance(chunks[session.chunkIndex]);
    utterance.lang = lang === 'hi' ? 'hi-IN' : 'en-IN';
    utterance.rate = 0.95;
    utterance.onend = () => {
      if (!isCurrent()) return;
      session.chunkIndex += 1;
      speakNext();
    };
    utterance.onerror = finish;
    window.speechSynthesis.speak(utterance);
  };

  speakNext();
}

// Toggles read-aloud for a given button + text. If this button is the one
// currently reading, pauses it (remembering the position). Otherwise stops
// whatever else might be reading and starts this one — resuming from the
// remembered position if the last thing stopped was this same button with
// this same text, or fresh from the beginning otherwise.
function toggleSpeak(button, text, lang) {
  if (!speechSupported() || !button) return;
  if (isSpeakingButton(button)) {
    stopSpeaking({ keepPosition: true });
    return;
  }

  const resume = pausedSpeech
    && pausedSpeech.button === button
    && pausedSpeech.text === text
    && pausedSpeech.lang === lang
    ? pausedSpeech
    : null;

  stopSpeaking();
  if (!text) return;

  const chunks = resume ? resume.chunks : splitIntoSpeechChunks(text);
  const startIndex = resume ? resume.chunkIndex : 0;
  pausedSpeech = null;
  speakChunksFrom(button, chunks, startIndex, lang);
}

function addSpeakButton(quiz) {
  if (!speechSupported() || quiz.querySelector('.quiz-speak-btn')) return;
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'quiz-speak-btn';
  btn.setAttribute('aria-label', currentLang() === 'hi' ? 'यह प्रश्न ज़ोर से पढ़ें' : 'Read this question aloud');
  btn.setAttribute('aria-pressed', 'false');
  btn.textContent = '🔊';
  btn.style.display = currentLang() === 'hi' ? 'none' : '';
  btn.addEventListener('click', (event) => {
    event.preventDefault();
    speakQuiz(quiz, btn);
  });
  quiz.prepend(btn);
}

function speakQuiz(quiz, btn) {
  const lang = currentLang();
  const questionEl = Array.from(quiz.querySelectorAll('.quiz-question'))
    .find((el) => el.getAttribute('data-lang') === lang);
  const optionTexts = Array.from(quiz.querySelectorAll('.quiz-option')).map((opt) => {
    const span = Array.from(opt.querySelectorAll('[data-lang]'))
      .find((el) => el.getAttribute('data-lang') === lang);
    return (span || opt).textContent.trim();
  });

  const parts = [];
  if (questionEl) parts.push(questionEl.textContent.trim());
  optionTexts.forEach((text, index) => {
    parts.push(`${lang === 'hi' ? 'विकल्प' : 'Option'} ${index + 1}: ${text}`);
  });

  toggleSpeak(btn, parts.join('. '), lang);
}

function addLessonSpeakButton(container) {
  if (!speechSupported()) return;
  const actions = container.querySelector('.lesson-topbar-actions') || container.querySelector('.lesson-topbar');
  if (!actions || actions.querySelector('.lesson-speak-btn')) return;

  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'lesson-speak-btn secondary-btn';
  btn.setAttribute('aria-pressed', 'false');
  btn.innerHTML = `🔊 <span>${currentLang() === 'hi' ? 'पाठ सुनें' : 'Read lesson aloud'}</span>`;
  btn.style.display = currentLang() === 'hi' ? 'none' : '';
  btn.addEventListener('click', () => speakLessonBody(container, btn));
  actions.appendChild(btn);
}

function speakLessonBody(container, btn) {
  const lang = currentLang();
  const block = container.querySelector(`.lesson-content > [data-lang="${lang}"]`);
  const text = block ? (block.innerText || block.textContent || '').replace(/\s+/g, ' ').trim() : '';
  toggleSpeak(btn, text, lang);
}

// ---------------------------------------------------------------------------
// Printable / downloadable practice sheet (no answers shown)
// ---------------------------------------------------------------------------

function addPrintButton(container) {
  const actions = container.querySelector('.lesson-topbar-actions') || container.querySelector('.lesson-topbar');
  if (!actions || actions.querySelector('.lesson-print-btn')) return;

  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'lesson-print-btn secondary-btn';
  btn.innerHTML = `📝 <span>View practice sheet</span>`;
  btn.style.display = currentLang() === 'hi' ? 'none' : '';
  btn.addEventListener('click', () => openPracticeSheet(container));
  actions.appendChild(btn);
}

function openPracticeSheet(container) {
  const lang = currentLang();
  // Practice-sheet images are intentionally English-only. Hindi lessons do not
  // show or open this tool.
  if (lang === 'hi') return;

  const lessonId = container.querySelector('.quiz')?.dataset.lessonId || '';
  const worksheets = {
    l1: { title: 'Whole Numbers', src: 'data:image/jpeg;base64,' },
    l2: { title: 'Fractions', src: 'data:image/jpeg;base64,' },
    l3: { title: 'Geometry', src: 'data:image/png;base64,' },
    s1: { title: 'Plants Around Us', src: 'data:image/png;base64,' },
    s2: { title: 'States of Matter', src: 'data:image/png;base64,' }
  };
  const worksheet = worksheets[lessonId];
  if (!worksheet) return;

  let modal = document.querySelector('.worksheet-modal');
  if (!modal) {
    modal = document.createElement('div');
    modal.className = 'worksheet-modal';
    modal.innerHTML = `
      <div class="worksheet-modal-backdrop" data-close-sheet="true"></div>
      <div class="worksheet-modal-card" role="dialog" aria-modal="true" aria-labelledby="worksheet-modal-title">
        <div class="worksheet-modal-header">
          <div>
            <div class="worksheet-modal-kicker">Practice Sheet</div>
            <h2 id="worksheet-modal-title"></h2>
          </div>
          <button type="button" class="worksheet-close-btn" aria-label="Close practice sheet">×</button>
        </div>
        <div class="worksheet-modal-body">
          <img class="worksheet-modal-image" alt="Practice worksheet">
        </div>
      </div>`;
    document.body.appendChild(modal);

    const close = () => modal.classList.remove('is-open');
    modal.querySelector('.worksheet-close-btn').addEventListener('click', close);
    modal.querySelector('[data-close-sheet]').addEventListener('click', close);
    document.addEventListener('keydown', (event) => {
      if (event.key === 'Escape') close();
    });
  }

  modal.querySelector('#worksheet-modal-title').textContent = worksheet.title;
  const image = modal.querySelector('.worksheet-modal-image');
  image.src = worksheet.src;
  image.alt = `${worksheet.title} practice worksheet`;
  modal.classList.add('is-open');
  modal.querySelector('.worksheet-close-btn').focus();
}

function refreshToolLabels(target) {
  const speakButton = document.querySelector('.lesson-speak-btn');
  if (speakButton) {
    speakButton.style.display = target === 'hi' ? 'none' : '';
    const speakSpan = speakButton.querySelector('span');
    if (speakSpan) speakSpan.textContent = target === 'hi' ? 'पाठ सुनें' : 'Read lesson aloud';
  }

  const practiceButton = document.querySelector('.lesson-print-btn');
  if (practiceButton) {
    practiceButton.style.display = target === 'hi' ? 'none' : '';
    const span = practiceButton.querySelector('span');
    if (span) span.textContent = 'View practice sheet';
  }

  // Read-aloud is intentionally English-only; hide the per-question speaker
  // buttons entirely when the site is in Hindi mode.
  document.querySelectorAll('.quiz-speak-btn').forEach((btn) => {
    btn.style.display = target === 'hi' ? 'none' : '';
    btn.setAttribute('aria-label', target === 'hi' ? 'यह प्रश्न ज़ोर से पढ़ें' : 'Read this question aloud');
  });
}

function escapeHtml(value) { return String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('\"','&quot;').replaceAll("'",'&#039;'); }
